            ("राजकोषीय घाटा (Fiscal Deficit) का क्या तात्पर्य होता है?", "कुल व्यय में से कुल प्राप्तियों (उधारियों को छोड़कर) का अंतर (सरकार की कुल उधारी जरूरत)।", ["कुल व्यय - कुल प्राप्तियां (उधारी छोड़कर)", "राजस्व व्यय - राजस्व प्राप्ति", "ब्याज भुगतान", "कुल विदेशी ऋण"], 0, "Moderate"),
            ("योजना आयोग के स्थान पर 'नीति आयोग' (NITI Aayog) का गठन कब किया गया?", "1 जनवरी 2015 को नेशनल इंस्टीट्यूशन फॉर ट्रांसफॉर्मिंग इंडिया (NITI) बना।", ["1 जनवरी 2015", "15 अगस्त 2014", "1 अप्रैल 2015", "26 जनवरी 2016"], 0, "Easy"),
            ("नीति आयोग का पदेन अध्यक्ष (Ex-Officio Chairman) कौन होता है?", "भारत के प्रधानमंत्री नीति आयोग के पदेन अध्यक्ष होते हैं।", ["भारत के प्रधानमंत्री", "राष्ट्रपति", "वित्त मंत्री", "उपराष्ट्रपति"], 0, "Easy"),
            ("भारत की प्रथम पंचवर्षीय योजना (1951-56) किस आर्थिक मॉडल पर आधारित थी?", "हैरोड-डोमर मॉडल (Harrod-Domar Model) पर आधारित थी (कृषि पर बल)।", ["हैरोड-डोमर मॉडल", "पी.सी. महालनोबिस मॉडल", "गाडगिल योजना", "जॉन डब्ल्यू मिलर मॉडल"], 0, "Easy"),
            ("द्वितीय पंचवर्षीय योजना (1956-61) किस मॉडल पर आधारित थी जिसमें भारी उद्योगों पर बल दिया गया?", "प्रो. प्रशांत चंद्र महालनोबिस (P.C. Mahalanobis Model) पर आधारित थी।", ["पी.सी. महालनोबिस मॉडल", "हैरोड-डोमर मॉडल", "सर्वोदय मॉडल", "चक्रवर्ती मॉडल"], 0, "Easy"),
            ("1991 की नई आर्थिक नीति (LPG Reforms) के समय भारत के प्रधानमंत्री और वित्त मंत्री कौन थे?", "पी.वी. नरसिम्हा राव (PM) और डॉ. मनमोहन सिंह (वित्त मंत्री) थे।", ["पी.वी. नरसिम्हा राव एवं डॉ. मनमोहन सिंह", "राजीव गांधी एवं वी.पी. सिंह", "अटल बिहारी वाजपेयी एवं यशवंत सिन्हा", "चंद्रशेखर एवं यशवंत सिन्हा"], 0, "Easy"),
